// Lời kể được biên soạn mới từ truyện dân gian/ngụ ngôn thuộc phạm vi công cộng.
window.STORIES = [
{id:'rua-tho',title:'Rùa và Thỏ',category:'Ngụ ngôn',age:3,minutes:3,animal:'rabbit',friend:'turtle',color:'#e8edd4',tag:'Sự kiên trì',desc:'Từng bước nhỏ cũng đưa mình đến một đích thật xa.',moral:'Mỗi bạn có một thế mạnh. Kiên trì làm từng chút, không chê bai và không chủ quan sẽ giúp chúng mình tiến bộ.',scenes:[['Một lời thách đố','Thỏ chạy nhanh nhất khu rừng và thường trêu Rùa đi chậm. Rùa không giận. Một hôm, Rùa nhẹ nhàng rủ Thỏ cùng chạy tới cây sồi cuối con đường. Thỏ cười rồi đồng ý.'],['Cuộc đua bắt đầu','Cú mèo vừa hô bắt đầu, Thỏ đã lao đi như gió. Rùa chậm rãi bước theo. Thỏ ngoái lại, thấy bạn còn xa nên nghĩ: Mình nghỉ dưới bóng cây một lát cũng chẳng sao!'],['Những bước chân nhỏ','Thỏ nằm xuống rồi ngủ quên. Rùa vẫn đi đều, vượt qua viên đá, qua bụi hoa, rồi qua chỗ Thỏ đang ngủ. Mệt thì Rùa thở chậm, sau đó lại tiếp tục.'],['Niềm vui ở đích đến','Khi Thỏ tỉnh giấc, Rùa đã gần tới cây sồi. Thỏ chạy hết sức nhưng Rùa chạm đích trước. Thỏ xin lỗi vì đã chê bạn. Rùa mỉm cười: Chúng mình cùng cố gắng nhé!']],quiz:[['Vì sao Thỏ dừng lại giữa đường?',['Thỏ chủ quan và ngủ quên','Thỏ bị lạc','Thỏ đã về đích'],0],['Điều gì giúp Rùa về đích trước?',['Một chiếc xe','Sự kiên trì','Một đôi cánh'],1],['Khi bạn làm chậm hơn mình, bé nên làm gì?',['Chê bạn','Không chơi với bạn','Động viên và tôn trọng bạn'],2]]},
{id:'kien-bo-cau',title:'Kiến và Chim Bồ Câu',category:'Tình bạn',age:3,minutes:3,animal:'bird',friend:'ant',color:'#e2edf0',tag:'Biết giúp đỡ',desc:'Một chiếc lá nhỏ mở đầu cho một tình bạn thật lớn.',moral:'Ai cũng có thể giúp người khác theo cách của mình. Hãy biết cảm ơn và tìm người lớn hỗ trợ nếu tình huống nguy hiểm.',scenes:[['Bên dòng suối','Một chú Kiến ra suối tìm nước uống. Bờ đất ướt khiến chú trượt chân xuống dòng nước. Kiến cố bám vào một cọng cỏ nhưng nước cứ đưa chú ra xa.'],['Chiếc lá cứu bạn','Bồ Câu trên cành cây nhìn thấy Kiến đang chới với. Cô thả một chiếc lá xuống bên cạnh. Kiến trèo lên lá và theo dòng nước trôi vào bờ. Chú vẫy râu cảm ơn cô bạn tốt bụng.'],['Một việc bất ngờ','Vài hôm sau, có người giăng lưới gần chỗ Bồ Câu đang đậu. Kiến thấy vậy liền chạy đến đốt vào chân người ấy. Người giăng lưới giật mình kêu lên, làm Bồ Câu chú ý.'],['Đôi bạn của khu rừng','Bồ Câu vỗ cánh bay khỏi chiếc lưới. Cô trở lại cảm ơn Kiến. Chú Kiến bé xíu cũng có thể giúp bạn! Từ đó, hai bạn luôn quan tâm đến nhau bên dòng suối nhỏ.']],quiz:[['Bồ Câu thả gì xuống cứu Kiến?',['Viên đá','Chiếc lá','Cành cây khô'],1],['Kiến đã làm gì để báo động?',['Đốt vào chân người giăng lưới','Đi ngủ','Trốn vào tổ'],0],['Khi được giúp đỡ, bé nên nói gì?',['Không nói gì','Đi chỗ khác','Cảm ơn bạn'],2]]},
{id:'bo-dua',title:'Câu Chuyện Bó Đũa',category:'Cổ tích',age:6,minutes:4,animal:'bear',friend:'bird',color:'#f2e6d4',tag:'Yêu thương gia đình',desc:'Bài học giản dị của người cha từ những chiếc đũa.',moral:'Gia đình mạnh mẽ hơn khi mọi người biết lắng nghe, nhường nhịn và cùng giải quyết khó khăn.',scenes:[['Người cha lo lắng','Trong một gia đình nọ, những người con thường tranh cãi vì chuyện nhỏ. Người cha buồn lắm. Ông muốn các con hiểu rằng sự hòa thuận quý hơn việc lúc nào cũng giành phần đúng.'],['Thử bẻ bó đũa','Một buổi sáng, cha đặt bó đũa lên bàn và mời từng người bẻ thử. Người anh gắng sức, người em cũng thử, nhưng bó đũa vẫn nguyên vẹn. Ai nấy nhìn nhau ngạc nhiên.'],['Từng chiếc một','Cha tháo sợi dây buộc rồi bẻ từng chiếc đũa. Lần này việc ấy thật dễ dàng. Ông nói: Khi đứng riêng lẻ, chúng ta dễ gặp khó. Khi cùng nhau, chúng ta có thêm sức mạnh.'],['Một mái nhà ấm áp','Những người con hiểu ý cha. Họ nói lời xin lỗi và cùng sửa lại hàng rào trong vườn. Công việc xong nhanh hơn, tiếng cười cũng trở về. Từ đó, họ cố gắng lắng nghe nhau nhiều hơn.']],quiz:[['Những người con có bẻ gãy cả bó đũa không?',['Không','Có ngay lập tức','Chưa ai thử'],0],['Cha bẻ đũa bằng cách nào?',['Dùng một hòn đá','Bẻ từng chiếc','Nhờ gió thổi'],1],['Câu chuyện nhắc chúng mình điều gì?',['Luôn tranh phần thắng','Làm mọi việc một mình','Yêu thương và đoàn kết'],2]]},
{id:'cao-nho',title:'Cáo và Chùm Nho',category:'Ngụ ngôn',age:6,minutes:2,animal:'fox',friend:'bird',color:'#eee3ec',tag:'Sự trung thực',desc:'Chùm nho ở quá cao, còn lời nói thật ở rất gần.',moral:'Chưa làm được một việc không có nghĩa việc ấy không tốt. Mình có thể thừa nhận khó khăn, thử cách khác hoặc nhờ giúp đỡ.',scenes:[['Giàn nho tím','Cáo đi qua khu vườn và thấy những chùm nho tím mọng dưới tán lá. Trời nắng, Cáo vừa đói vừa khát. Chú ngước nhìn giàn nho cao và muốn hái một chùm.'],['Nhảy lên nào','Cáo nhún chân nhảy, rồi nhảy thêm lần nữa. Nhưng chùm nho vẫn ở quá cao. Sau nhiều lần thử, Cáo ngồi xuống thở. Chú chưa nghĩ ra một cách khác để hái nho.'],['Một lời chê vội','Không lấy được nho, Cáo quay đi và nói: Chắc nho ấy chua lắm, mình chẳng thích đâu! Chim Sẻ ở gần đó nghiêng đầu: Cậu chưa nếm, sao biết nho chua nhỉ?'],['Dám nói điều thật','Cáo dừng lại, ngượng ngùng đáp: Thật ra mình chưa với tới được. Chim Sẻ gật đầu. Thừa nhận mình chưa làm được cũng cần can đảm, phải không nào?']],quiz:[['Cáo muốn lấy thứ gì?',['Củ cà rốt','Chùm nho','Quả táo'],1],['Vì sao Cáo chưa hái được nho?',['Nho ở quá cao','Nho bị giấu','Cáo không nhìn thấy'],0],['Chưa làm được việc gì, bé có thể làm gì?',['Chê việc ấy ngay','Giận mọi người','Thử cách khác hoặc nhờ giúp'],2]]},
{id:'doi-ban',title:'Đôi Bạn Nhỏ',category:'Tình bạn',age:3,minutes:3,animal:'duck',friend:'chick',color:'#e9edce',tag:'Quan tâm bạn bè',desc:'Gà con và Vịt con có những tài năng rất khác nhau.',moral:'Bạn bè có những khả năng khác nhau. Biết quan tâm và giúp đỡ sẽ làm tình bạn đẹp hơn. Trẻ nhỏ chỉ chơi gần nước khi có người lớn trông coi.',scenes:[['Buổi sáng trong vườn','Gà con và Vịt con chơi ở khu vườn bên ao. Gà mẹ ở gần đó chăm luống rau. Gà con bới đất rất giỏi, còn Vịt con có thể bơi nhẹ nhàng trên mặt nước.'],['Một tiếng gọi','Khi Gà mẹ quay vào lấy giỏ, Cáo bất ngờ xuất hiện sau bụi cây. Gà con sợ quá gọi bạn. Vịt con bơi sát bờ, đón Gà lên lưng và đưa ra chỗ Cáo không với tới.'],['Mọi người đã an toàn','Gà mẹ nghe tiếng liền chạy đến gọi người giúp. Cáo bỏ đi. Gà con và Vịt con trở lại bờ cùng mẹ. Hai bạn cảm ơn nhau rồi ngồi nghỉ dưới bóng cây.'],['Bạn cũng giỏi mà','Trên đường về, chân Vịt vướng một sợi dây leo. Gà dùng mỏ gỡ dây cho bạn. Vịt vui vẻ nói: Cậu cũng giúp tớ được đấy! Mỗi bạn một tài, cùng nhau thật vui.']],quiz:[['Bạn nào bơi giỏi?',['Gà con','Vịt con','Cả hai đều không biết'],1],['Gà đã giúp Vịt việc gì?',['Gỡ dây leo vướng chân','Dạy bay','Xây một ngôi nhà'],0],['Khi chơi gần ao hồ, bé cần gì?',['Tự đi một mình','Nhảy xuống thử','Người lớn trông coi'],2]]},
{id:'su-tu-chuot',title:'Sư Tử và Chuột Nhắt',category:'Ngụ ngôn',age:3,minutes:3,animal:'lion',friend:'mouse',color:'#f0e8c9',tag:'Lòng tốt',desc:'Một người bạn bé xíu cũng có thể làm điều phi thường.',moral:'Đừng đánh giá bạn chỉ qua vẻ ngoài. Một hành động tử tế có thể mở đầu cho nhiều điều tốt đẹp.',scenes:[['Giấc ngủ của Sư Tử','Sư Tử đang ngủ dưới tán cây. Chuột Nhắt chạy qua, vô tình làm cành lá động đậy khiến Sư Tử thức giấc. Chuột vội xin lỗi và mong được trở về nhà.'],['Một lời hứa nhỏ','Sư Tử thấy Chuột lễ phép nên để bạn đi. Chuột cảm ơn rồi nói: Có dịp, tôi sẽ giúp bác! Sư Tử mỉm cười, chưa biết người bạn nhỏ ấy có thể giúp mình bằng cách nào.'],['Chiếc lưới trong rừng','Một hôm, Sư Tử mắc vào tấm lưới bị bỏ trong rừng. Càng vùng vẫy, dây càng siết. Nghe tiếng gọi, Chuột Nhắt chạy tới. Bạn bình tĩnh tìm những nút dây sát mặt đất.'],['Hàm răng bé mà giỏi','Chuột kiên nhẫn cắn đứt từng sợi dây. Cuối cùng, tấm lưới bung ra và Sư Tử bước được ra ngoài. Sư Tử cúi đầu cảm ơn: Bạn nhỏ của tôi, việc bạn làm thật lớn lao!']],quiz:[['Ai mắc vào chiếc lưới?',['Sư Tử','Chuột Nhắt','Chim Sẻ'],0],['Chuột giúp bạn bằng cách nào?',['Thổi bay lưới','Cắn đứt dây lưới','Đẩy một tảng đá'],1],['Có nên coi thường bạn nhỏ bé không?',['Có','Chỉ khi mình khỏe','Không, ai cũng có điểm mạnh'],2]]},
{id:'qua-nuoc',title:'Quạ và Chiếc Bình Nước',category:'Ngụ ngôn',age:6,minutes:3,animal:'crow',friend:'bird',color:'#dce8e4',tag:'Trí thông minh',desc:'Một ý tưởng nhỏ làm mực nước dâng lên từng chút.',moral:'Khi gặp khó khăn, hãy bình tĩnh quan sát và thử những cách phù hợp. Kiên nhẫn giúp ý tưởng trở thành kết quả.',scenes:[['Ngày nắng nóng','Quạ bay qua cánh đồng trong buổi trưa nắng. Tìm mãi, bạn mới thấy một chiếc bình có chút nước dưới đáy. Quạ vui lắm, vội đậu xuống bên cạnh.'],['Chiếc cổ bình dài','Mỏ Quạ không chạm được tới nước vì cổ bình dài và hẹp. Bình lại nặng, bạn không thể nghiêng được. Quạ ngừng lại, nhìn quanh thay vì cố làm chiếc bình đổ.'],['Những viên sỏi sạch','Bên cạnh có những viên sỏi nhỏ. Quạ thả thử một viên vào bình. Nước nhích lên một chút! Quạ tiếp tục nhặt từng viên sỏi và thả vào, rất cẩn thận.'],['Một ngụm nước mát','Mực nước dâng tới chỗ mỏ Quạ có thể chạm. Quạ uống nước rồi nghỉ dưới bóng cây. Nhờ quan sát và kiên nhẫn, bạn đã tìm được cách giải quyết việc khó.']],quiz:[['Vì sao Quạ không uống được nước lúc đầu?',['Nước quá nóng','Nước ở quá thấp','Không có bình'],1],['Quạ thả gì vào bình?',['Những viên sỏi','Lá khô','Hạt thóc'],0],['Khi gặp việc khó, mình nên làm gì?',['Đập vỡ đồ vật','Bỏ ngay lập tức','Bình tĩnh quan sát, tìm cách'],2]]},
{id:'gio-mat-troi',title:'Gió và Mặt Trời',category:'Ngụ ngôn',age:6,minutes:3,animal:'bear',friend:'bird',color:'#f2e6cb',tag:'Sự dịu dàng',desc:'Sức mạnh đôi khi đến từ những điều thật ấm áp.',moral:'Sự dịu dàng và thấu hiểu thường hiệu quả hơn ép buộc. Hãy thử nói chuyện nhẹ nhàng để người khác cảm thấy an tâm.',scenes:[['Ai mạnh hơn?','Gió và Mặt Trời tranh luận xem ai mạnh hơn. Nhìn thấy một người đang đi trên đường, họ cùng thử xem ai khiến người ấy tự cởi chiếc áo khoác trước.'],['Gió thổi thật mạnh','Gió thổi ào ào. Cây nghiêng, bụi bay, chiếc áo của người đi đường phấp phới. Nhưng trời càng lạnh, người ấy càng kéo áo sát vào mình và giữ thật chặt.'],['Ánh nắng dịu êm','Đến lượt Mặt Trời. Không ồn ào, Mặt Trời tỏa những tia nắng ấm. Gió lặng xuống, con đường dễ đi hơn. Người đi đường cảm thấy thoải mái và bước chậm lại.'],['Một bài học ấm áp','Khi thấy đủ ấm, người ấy tự cởi áo khoác và ngồi nghỉ dưới cây. Gió hiểu ra: Không phải cứ làm thật mạnh là sẽ được việc. Dịu dàng cũng là một sức mạnh.']],quiz:[['Gió thổi mạnh khiến người đi đường làm gì?',['Giữ chặt áo hơn','Cởi áo ngay','Chạy về biển'],0],['Ai khiến người ấy tự cởi áo?',['Gió','Mặt Trời','Mặt Trăng'],1],['Cách cư xử nào được nhắc đến?',['Ép bạn làm theo','Quát thật to','Nhẹ nhàng và thấu hiểu'],2]]},
{id:'ba-chu-heo',title:'Ba Chú Heo Con',category:'Cổ tích',age:3,minutes:4,animal:'pig',friend:'pig',color:'#f0dfdb',tag:'Sự chuẩn bị',desc:'Một ngôi nhà vững chãi cần thời gian và sự chăm chút.',moral:'Làm cẩn thận và biết chuẩn bị giúp chúng mình an toàn hơn. Khi gặp nguy hiểm, hãy tìm nơi an toàn và gọi người lớn giúp đỡ.',scenes:[['Ba ngôi nhà','Ba chú Heo muốn làm nhà. Heo Cả chọn rơm để xây cho nhanh. Heo Hai dùng cành cây. Heo Út dành nhiều ngày xếp từng viên gạch, làm nền và cánh cửa thật chắc.'],['Vị khách không mời','Sói đến gõ cửa nhà rơm. Heo Cả không mở, nhưng Sói thổi mạnh khiến rơm bay tung. Heo Cả chạy sang nhà gỗ của anh em. Cả hai vẫn chưa thấy yên tâm.'],['Cùng tới nhà gạch','Sói thổi tiếp làm những cành cây rơi xuống. Hai chú Heo nhanh chóng chạy tới nhà gạch. Heo Út đón hai anh vào, khóa cửa và gọi hàng xóm tới giúp.'],['Mái ấm vững vàng','Sói thổi mãi mà tường gạch không lay chuyển. Nghe tiếng hàng xóm đến, Sói bỏ đi. Ba anh em ôm nhau rồi cùng dựng lại những ngôi nhà chắc chắn. Việc cẩn thận thật đáng công!']],quiz:[['Heo Út xây nhà bằng gì?',['Rơm','Gạch','Lá cây'],1],['Khi gặp Sói, các chú Heo tìm đến đâu?',['Nhà gạch an toàn','Giữa khu rừng','Bờ suối'],0],['Câu chuyện khuyên mình điều gì?',['Làm thật vội','Không cần chuẩn bị','Làm cẩn thận, biết nhờ giúp'],2]]},
{id:'hat-mam',title:'Hạt Mầm Bé Xíu',category:'Trước giờ ngủ',age:3,minutes:3,animal:'rabbit',friend:'bird',color:'#e6ead8',tag:'Kiên nhẫn lớn lên',desc:'Một câu chuyện mới về những điều đang lớn lên âm thầm.',moral:'Mỗi người lớn lên theo nhịp riêng. Hãy chăm sóc bản thân và kiên nhẫn với những điều mình đang học.',scenes:[['Trong lòng đất','Một hạt mầm nằm yên trong đất mềm. Bên trên, khu vườn đã có nhiều bông hoa. Hạt mầm nghĩ: Bao giờ mình mới được nhìn thấy bầu trời nhỉ? Đất dịu dàng ôm lấy bạn.'],['Cơn mưa nhỏ','Đêm ấy, mưa gõ những tiếng tí tách. Hạt mầm uống từng giọt nước và cảm thấy mình thay đổi. Một chiếc rễ bé xíu bắt đầu mọc ra. Bạn vẫn chưa thấy mặt trời, nhưng bạn đang lớn.'],['Một chiếc lá đầu tiên','Sáng nọ, mầm xanh nhú khỏi mặt đất. Bạn gặp Thỏ đang tưới vườn. Thỏ reo: Chào chiếc lá nhỏ! Hạt mầm nhìn xung quanh. Bầu trời rộng và xanh hơn cả điều bạn tưởng tượng.'],['Ngủ ngoan nhé','Chiều xuống, chiếc lá khép nhẹ trong gió. Mầm biết ngày mai mình sẽ lớn thêm một chút. Không cần vội. Trong khu vườn yên ả, bạn ngủ ngon dưới ánh trăng dịu dàng.']],quiz:[['Hạt mầm nằm ở đâu lúc đầu?',['Trong lòng đất','Trên đám mây','Trong chiếc cốc khô'],0],['Điều gì giúp hạt mầm có nước?',['Tiếng hát','Cơn mưa','Ánh trăng'],1],['Mỗi người có lớn lên giống hệt nhau không?',['Luôn giống hệt','Phải nhanh nhất','Không, mỗi người có nhịp riêng'],2]]},
{id:'tho-trang',title:'Thỏ Con Chào Mặt Trăng',category:'Trước giờ ngủ',age:3,minutes:3,animal:'rabbit',friend:'mouse',color:'#dfe3ee',tag:'Thói quen buổi tối',desc:'Chào một ngày thật vui, đón một giấc mơ thật hiền.',moral:'Một thói quen buổi tối nhẹ nhàng giúp mình thư giãn: cất đồ chơi, vệ sinh cá nhân và dành thời gian ấm áp bên gia đình.',scenes:[['Khu vườn lên đèn','Mặt trời đi ngủ sau ngọn đồi. Thỏ Con vẫn muốn chơi thêm. Mẹ chỉ lên bầu trời: Con nhìn xem, Mặt Trăng đã tới rồi. Chúng mình cùng chào buổi tối nhé.'],['Tạm biệt đồ chơi','Thỏ đặt từng khối gỗ vào giỏ, xếp sách lên kệ. Cảm ơn các bạn vì một ngày vui! Căn phòng gọn gàng hơn. Thỏ cũng thấy lòng mình yên hơn một chút.'],['Một lời cảm ơn','Đánh răng và rửa mặt xong, Thỏ nép bên mẹ. Hôm nay con thích nhất lúc tưới cây cùng mẹ. Mẹ ôm Thỏ: Mẹ cũng rất vui vì có con ở bên.'],['Chào nhé, Mặt Trăng','Thỏ kéo chăn lên, nhìn vầng trăng ngoài cửa sổ. Gió khẽ đưa lá, căn nhà thật ấm. Thỏ thì thầm chúc mọi người ngủ ngon rồi nhắm mắt, mang theo một nụ cười nhỏ.']],quiz:[['Trước khi ngủ, Thỏ cất gì?',['Đồ chơi và sách','Những đám mây','Mặt Trăng'],0],['Thỏ làm gì sau khi cất đồ chơi?',['Ra vườn một mình','Đánh răng, rửa mặt','Chạy nhảy thật lâu'],1],['Một việc nhẹ nhàng trước giờ ngủ là gì?',['La hét thật to','Chơi mãi không nghỉ','Nghe truyện bên người thân'],2]]},
{id:'ban-gau',title:'Gấu Con Biết Xin Lỗi',category:'Tình bạn',age:3,minutes:3,animal:'bear',friend:'rabbit',color:'#eadfce',tag:'Biết nhận lỗi',desc:'Hai tiếng xin lỗi giúp một ngày buồn trở nên ấm áp.',moral:'Ai cũng có lúc mắc lỗi. Biết nói lời xin lỗi, lắng nghe và cùng sửa lại là cách chăm sóc tình bạn.',scenes:[['Ngọn tháp của Thỏ','Thỏ xếp một ngọn tháp bằng gỗ rất đẹp. Gấu Con ôm quả bóng chạy ngang, không để ý nên va vào tháp. Những khối gỗ đổ xuống sàn. Thỏ đứng lặng, buồn rầu.'],['Một chút ngượng ngùng','Gấu định nói: Tại tháp của cậu ở giữa đường! Nhưng nhìn thấy đôi tai Thỏ cụp xuống, Gấu biết bạn đã mất nhiều công. Gấu hít một hơi rồi đặt quả bóng xuống.'],['Hai tiếng dịu dàng','Tớ xin lỗi vì chạy vội làm đổ tháp. Tớ có thể giúp cậu xếp lại không? Thỏ gật đầu. Gấu lắng nghe bạn chỉ chỗ đặt từng khối gỗ, cẩn thận hơn lúc trước.'],['Ngọn tháp mới','Hai bạn cùng xếp được một ngọn tháp có cả chiếc cầu. Thỏ vui trở lại. Gấu nhớ từ nay sẽ chơi bóng ngoài sân. Một lời xin lỗi cùng hành động sửa sai đã giữ tình bạn thật ấm.']],quiz:[['Vì sao ngọn tháp đổ?',['Gấu chạy va vào','Trời mưa','Thỏ đem cất'],0],['Gấu đã làm gì để sửa lỗi?',['Bỏ đi','Xin lỗi và cùng xếp lại','Giấu các khối gỗ'],1],['Lỡ làm bạn buồn, mình nên làm gì?',['Đổ lỗi cho bạn','Không nói gì','Nhận lỗi và tìm cách sửa'],2]]}
];
